unsigned char type_skill_quest::is_satisfied(hero* current_hero)
{
    for (int i = 0; i < 4; ++i) {
        int have;

        if (current_hero->stats[i] > 99)
            have = 99;
        else if (current_hero->stats[i] > 0)
            have = current_hero->stats[i];
        else
            have = i >= 2;
        if (have < required_skills[i])
            return 0;
    }
    return 1;
}

